/**
 * Loads the fixture dataset by replaying `@quant-fusion/research-store`'s migrations into a fresh
 * in-memory database — instead of constructing it inline in TypeScript or reading a checked-in
 * JSON file. See `scripts/generateFusionSeedMigration.ts` for how the seed migration was produced
 * (a mechanical, lossless dump of what this function used to load from `data/dataset.json`), and
 * `scripts/applyResearchUpdate.ts` for how it grows afterward — each research update lands as its
 * own new migration file, with no coding agent hand-editing this file required. The exported
 * name/signature is unchanged from the previous versions, so every consumer (bots, tests) is
 * unaffected by this move.
 *
 * Throws loudly on a validation failure rather than silently loading a partial/corrupted dataset
 * — migration content that fails `@quant-fusion/research-core`'s own validation is a bug that must
 * be fixed before anything else runs, not tolerated.
 */
export function createFusionFixtureDataset(): ResearchDataset {
  const store = createResearchStore(':memory:');
  try {
    const result = getResearchDataset(store, FUSION_DATASET_ID);
    if (!result.ok) {
      throw new Error(
        `fusion research dataset "${FUSION_DATASET_ID}" failed to load: ${result.reason}`,
      );
    }
    return result.value;
  } finally {
    closeResearchStore(store);
  }
}
